import { getComBankInfo } from '~/entities/comcode/lib/get-combank-info';
import { COM_CODE } from '~/entities/comcode/model/constants';
import { useComCodeState } from './use-comcode-state';

export const useComBankInfo = (walletInsttCd?: string | null) => {
  const { comCode } = useComCodeState(COM_CODE.BANK);
  return getComBankInfo(walletInsttCd, comCode);
};
